"""Foxglove data-platform client."""

from __future__ import annotations

import os
from datetime import datetime
from typing import Optional

import httpx


class ApiError(RuntimeError):
    """Raised when an API call fails."""


def http_error(resp: httpx.Response) -> str:
    """Concise ``reason (HTTP <code>[, <api_code>])`` summary."""
    reason = resp.reason_phrase or "Request failed"
    try:
        body = resp.json()
    except ValueError:
        return f"{reason} (HTTP {resp.status_code})"
    if isinstance(body, dict):
        message = body.get("error") or body.get("message") or reason
        api_code = body.get("code")
        if api_code:
            return f"{message} (HTTP {resp.status_code}, {api_code})"
        return f"{message} (HTTP {resp.status_code})"
    return f"{reason} (HTTP {resp.status_code})"


class FoxgloveClient:
    """Minimal authenticated client for the upload + event steps."""

    def __init__(self, api_url: str, bearer_token: str) -> None:
        self._http = httpx.Client(
            base_url=api_url,
            headers={"Authorization": f"Bearer {bearer_token}"},
            timeout=60.0,
        )

    def close(self) -> None:
        self._http.close()

    def __enter__(self) -> "FoxgloveClient":
        return self

    def __exit__(self, *_exc: object) -> None:
        self.close()

    def org_slug(self) -> str:
        """Return the signed-in user's organization slug (for building app links)."""
        resp = self._http.get("/v1/me")
        if resp.status_code != 200:
            raise ApiError(http_error(resp))
        return resp.json()["orgSlug"]

    def get_recording(self, key_or_id: str) -> Optional[dict]:
        """Fetch a recording by upload ``key`` or ``rec_...`` id."""
        resp = self._http.get(f"/v1/recordings/{key_or_id}")
        if resp.status_code == 200:
            return resp.json()
        if resp.status_code == 404:
            return None
        raise ApiError(http_error(resp))

    def upload_mcap(
        self,
        path: str,
        *,
        device_name: str,
        project_id: Optional[str] = None,
        filename: Optional[str] = None,
        key: Optional[str] = None,
    ) -> dict:
        """Register the recording, then PUT the file bytes to the signed URL."""
        body: dict = {
            "filename": filename or os.path.basename(path),
            "deviceName": device_name,
        }
        if project_id:
            body["projectId"] = project_id
        if key:
            body["key"] = key

        resp = self._http.post("/v1/data/upload", json=body)
        if resp.status_code != 200:
            raise ApiError(http_error(resp))
        data = resp.json()

        link = data.get("link")
        if not link:
            raise ApiError(f"upload response missing 'link': {data}")

        with open(path, "rb") as handle:
            put = httpx.put(
                link,
                content=handle.read(),
                headers={"Content-Type": "application/octet-stream"},
                timeout=300.0,
            )
        if put.status_code not in (200, 201):
            raise ApiError(http_error(put))
        return data

    def create_event(
        self,
        *,
        device_name: str,
        start: datetime,
        end: datetime,
        metadata: dict,
        project_id: Optional[str] = None,
    ) -> dict:
        """Create an event on ``device_name`` spanning ``start``..``end``."""
        body: dict = {
            "deviceName": device_name,
            "start": _rfc3339(start),
            "end": _rfc3339(end),
            "metadata": metadata,
        }
        if project_id:
            body["projectId"] = project_id

        resp = self._http.post("/v1/events", json=body)
        if resp.status_code not in (200, 201):
            raise ApiError(http_error(resp))
        return resp.json()


def _rfc3339(value: datetime) -> str:
    return value.isoformat().replace("+00:00", "Z")
